// Sample Stripe charges for a manual test run, created yesterday at 12:00 UTC.
// Amounts are in the smallest currency unit, exactly as Stripe returns them.
const noonYesterday = Math.floor(Date.now() / 86400000) * 86400 - 43200;
const charge = (id, amount, currency, extra = {}) => ({
  json: { id, amount, currency, status: 'succeeded', amount_refunded: 0, created: noonYesterday, ...extra },
});

return [
  charge('ch_001', 7900, 'usd'),
  charge('ch_002', 2900, 'eur'),
  charge('ch_003', 150000, 'ars'),
  charge('ch_004', 9900, 'gbp', { amount_refunded: 2000 }), // partially refunded
  charge('ch_005', 7900, 'usd', { status: 'failed' }),      // not revenue
  charge('ch_006', 4500, 'brl'),
  charge('ch_007', 12000, 'jpy'),                            // zero-decimal currency
  charge('ch_008', 25000, 'clp'),                            // zero-decimal currency
];

// Runs once, on the single response from ApogeoAPI "List All Rates":
// { base: 'USD', rates: { EUR: 0.8654, ARS: 1510.32, ... }, count, lastUpdated, stale }
// rates[CUR] is how many units of CUR equal one unit of the base currency.
const fx = $input.first().json;
const rates = { ...(fx.rates || {}) };
const base = String(fx.base || 'USD').toUpperCase();
rates[base] = 1;

const REPORTING = 'USD'; // change to report in EUR, GBP, etc.

if (!rates[REPORTING]) {
  throw new Error(`No exchange rate found for reporting currency ${REPORTING}. Check the REPORTING constant.`);
}

// Stripe amounts are in the currency's smallest unit. Most currencies have two
// decimals, but these do not (https://docs.stripe.com/currencies).
const ZERO_DECIMAL = ['BIF', 'CLP', 'DJF', 'GNF', 'JPY', 'KMF', 'KRW', 'MGA', 'PYG', 'RWF', 'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF'];
const THREE_DECIMAL = ['BHD', 'JOD', 'KWD', 'OMR', 'TND'];
function toMajorUnits(minor, cur) {
  if (ZERO_DECIMAL.includes(cur)) return minor;
  if (THREE_DECIMAL.includes(cur)) return minor / 1000;
  return minor / 100;
}

// Convert an amount in `cur` to the reporting currency, going through the base.
function toReporting(amount, cur) {
  const rate = rates[cur];
  if (!rate) return null;
  return (amount / rate) * rates[REPORTING];
}

// Reconcile yesterday as a full UTC day: [00:00, 24:00).
const now = new Date();
const dayEnd = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()) / 1000;
const dayStart = dayEnd - 86400;
const day = new Date(dayStart * 1000).toISOString().slice(0, 10);

// Charges come from Stripe on a scheduled run, or from the sample node on a manual test run.
let items = [];
try { items = $('Fetch Stripe Charges').all(); } catch (e) {}
if (!items.length) {
  try { items = $('Generate Sample Stripe Charges').all(); } catch (e) {}
}

// Only successful charges created yesterday. The Stripe node outputs an empty
// item on a day with no charges, so the day still gets a row.
const charges = items
  .map((item) => item.json)
  .filter((c) => c && c.id && c.status === 'succeeded' && c.created >= dayStart && c.created < dayEnd);

const perCurrency = {};
const unconverted = [];
let grandTotal = 0;

for (const charge of charges) {
  const cur = String(charge.currency || '').toUpperCase();
  const net = toMajorUnits(Number(charge.amount || 0) - Number(charge.amount_refunded || 0), cur);
  const converted = toReporting(net, cur);
  if (converted === null) {
    unconverted.push({ id: charge.id, currency: cur, amount: net });
    continue;
  }
  const row = perCurrency[cur] || (perCurrency[cur] = { currency: cur, count: 0, net_total: 0, reporting_total: 0 });
  row.count += 1;
  row.net_total += net;
  row.reporting_total += converted;
  grandTotal += converted;
}

const round = (n, decimals) => Math.round(n * 10 ** decimals) / 10 ** decimals;
const ratesStale = fx.stale === true;

return [{
  json: {
    date: day,
    reporting_currency: REPORTING,
    charge_count: charges.length,
    grand_total_reporting: round(grandTotal, 2),
    per_currency: Object.values(perCurrency).map((r) => ({
      ...r,
      net_total: round(r.net_total, 3),
      reporting_total: round(r.reporting_total, 2),
    })),
    unconverted,
    usd_eur_rate: rates.EUR || null,
    rate_base: base,
    rates_last_updated: fx.lastUpdated || null,
    rates_stale: ratesStale,
    needs_review: ratesStale || unconverted.length > 0,
  },
}];

